import type { ReactNode } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export type AlertTone = "info" | "success" | "warning" | "danger";

export interface AlertProps extends Omit<ViewProps, "children"> {
  tone?: AlertTone;
  title: string;
  children?: ReactNode;
  /** Controls visibility. Leave it out for an alert that is always shown. */
  open?: boolean;
  /** Shows a dismiss button when given. */
  onDismiss?: () => void;
  /** Extend the inner, named parts of the alert: icon, copy, title, description or dismiss. The React Native counterpart of `classNames`. */
  styles?: {
    icon?: StyleProp<ViewStyle>;
    copy?: StyleProp<ViewStyle>;
    title?: StyleProp<TextStyle>;
    description?: StyleProp<TextStyle>;
    dismiss?: StyleProp<ViewStyle>;
  };
}

const glyph: Record<AlertTone, string> = { info: "i", success: "✓", warning: "!", danger: "×" };

export function Alert({ tone = "info", title, children, open = true, onDismiss, style, styles: parts, ...props }: AlertProps) {
  const tokens = useTokens();
  if (!open) return null;

  const color = { info: tokens.accent, success: tokens.success, warning: tokens.warning, danger: tokens.danger }[tone];

  return (
    <View
      {...props}
      accessibilityRole="alert"
      style={[local.root, { borderColor: tokens.border, backgroundColor: tokens.surface }, style]}
    >
      <View style={[local.icon, { borderColor: color }, parts?.icon]}>
        <Text style={[local.glyph, { color }]}>{glyph[tone]}</Text>
      </View>
      <View style={[local.copy, parts?.copy]}>
        <Text style={[local.title, { color: tokens.foreground }, parts?.title]}>{title}</Text>
        {children ? (
          typeof children === "string" ? (
            <Text style={[local.description, { color: tokens.textSecondary }, parts?.description]}>{children}</Text>
          ) : (
            children
          )
        ) : null}
      </View>
      {onDismiss ? (
        <Pressable accessibilityRole="button" accessibilityLabel="Dismiss" hitSlop={8} onPress={onDismiss} style={[local.dismiss, parts?.dismiss]}>
          <Text style={{ color: tokens.textMuted, fontSize: 18, lineHeight: 20 }}>×</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "flex-start", gap: metrics.space[3], borderWidth: 1, borderRadius: metrics.radiusControl, padding: metrics.space[4] },
  icon: { width: 18, height: 18, marginTop: 1, borderWidth: 1.5, borderRadius: 9, alignItems: "center", justifyContent: "center" },
  glyph: { fontSize: 11, fontWeight: "700", lineHeight: 13 },
  copy: { flex: 1, gap: 4 },
  title: { fontSize: metrics.text.sm, fontWeight: "500" },
  description: { fontSize: metrics.text.xs },
  dismiss: { width: 28, height: 28, marginTop: -5, marginRight: -6, alignItems: "center", justifyContent: "center", borderRadius: metrics.radiusPill },
});

export default Alert;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
